#include <pthread.h>
#include <stdio.h>

void *worker(void *arg) {
    printf("%s\n", (char *) arg);
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    printf("main: begin\n");
    pthread_create(&t1, NULL, worker, "A");
    pthread_create(&t2, NULL, worker, "B");
    pthread_join(t1, NULL);   // A, B 출력 순서는 실행마다 다를 수 있다
    pthread_join(t2, NULL);
    printf("main: end\n");   // join 두 번 뒤라 항상 마지막
    return 0;
}
