#define _GNU_SOURCE
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/syscall.h>

static int counter = 0;
static long child_pid, child_tid;

static int child_fn(void *arg) {
    counter++;                          // CLONE_VM: 부모와 같은 메모리
    child_pid = syscall(SYS_getpid);    // TGID
    child_tid = syscall(SYS_gettid);    // TID
    return 0;
}

int main(void) {
    const size_t SZ = 1024 * 1024;
    char *stack = malloc(SZ);
    int flags = CLONE_VM | CLONE_FS | CLONE_FILES | CLONE_SIGHAND | CLONE_THREAD;
    clone(child_fn, stack + SZ, flags, NULL);   // 스택은 아래로 자라므로 끝 주소
    sleep(1);                           // CLONE_THREAD는 wait()로 기다릴 수 없다
    printf("child : pid=%ld tid=%ld\n", child_pid, child_tid);
    printf("parent: pid=%ld tid=%ld counter=%d\n",
           (long) syscall(SYS_getpid), (long) syscall(SYS_gettid), counter);
    return 0;
}
// 예상: 두 줄의 pid는 같고 tid만 다르며 counter=1
